insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ('vegetable-upma', 1, 'Measure the semolina (rava/sooji) and prepare the vegetables. Keep measured hot water nearby.'),
  ('vegetable-upma', 2, 'Heat oil in a heavy pan and temper mustard seeds and curry leaves until fragrant.'),
  ('vegetable-upma', 3, 'Add onion and vegetables; sauté until they begin to soften.'),
  ('vegetable-upma', 4, 'Stir in the semolina (rava/sooji) and toast briefly so each grain is coated.'),
  ('vegetable-upma', 5, 'Pour in hot water gradually, season, cover, and cook until tender.'),
  ('vegetable-upma', 6, 'Rest covered for 3 minutes, fluff gently, and serve with a squeeze of lemon.'),
  ('masala-dosa', 1, 'Combine the potato with the batter ingredients and enough water to make a pourable mixture.'),
  ('masala-dosa', 2, 'Rest the batter while you prepare any filling; keep the pan and oil ready.'),
  ('masala-dosa', 3, 'Heat a flat griddle over medium heat and wipe it lightly with oil.'),
  ('masala-dosa', 4, 'Pour a ladle of batter and spread it in a thin circle, working from the centre outwards.'),
  ('masala-dosa', 5, 'Cook until the edges lift and the underside is golden; add filling if the recipe calls for it.'),
  ('masala-dosa', 6, 'Fold or roll while hot and serve immediately with chutney or sambar.'),
  ('aloo-paratha', 1, 'Mix the flour with salt and the potato, then add water gradually to make a soft dough.'),
  ('aloo-paratha', 2, 'Knead briefly until smooth, cover, and rest for 10 minutes.'),
  ('aloo-paratha', 3, 'Divide the dough into equal portions and roll each one on a lightly floured surface.'),
  ('aloo-paratha', 4, 'Heat a tawa; cook each bread until bubbles appear, then turn and cook the other side.'),
  ('aloo-paratha', 5, 'Brush lightly with oil or ghee and cook until brown spots form.'),
  ('aloo-paratha', 6, 'Serve hot with curd, chutney, or a simple vegetable accompaniment.'),
  ('egg-bhurji-pav', 1, 'Prepare the whole egg: wash, drain, and cut or mash it as the recipe requires.'),
  ('egg-bhurji-pav', 2, 'Mix the flour with salt and spices, then add enough water to make a coating or soft mixture.'),
  ('egg-bhurji-pav', 3, 'Fold in the main ingredient and herbs until evenly coated.'),
  ('egg-bhurji-pav', 4, 'Shape into even pieces and heat a skillet with a thin layer of oil.'),
  ('egg-bhurji-pav', 5, 'Cook in batches, turning once, until crisp outside and fully cooked in the centre.'),
  ('egg-bhurji-pav', 6, 'Drain briefly and serve hot with chutney or lemon.'),
  ('bengali-khichuri', 1, 'Rinse the rice until the water runs mostly clear, then soak for 10 minutes and drain.'),
  ('bengali-khichuri', 2, 'Chop the aromatics and prepare the vegetables or protein before heating the pan.'),
  ('bengali-khichuri', 3, 'Warm oil, bloom cumin and whole spices, then cook the onion until soft.'),
  ('bengali-khichuri', 4, 'Add the split mung beans (moong dal), raw, tomato and seasoning; stir until coated with the spice base.'),
  ('bengali-khichuri', 5, 'Add rice and measured water, bring to a simmer, cover, and cook until the grains are tender.'),
  ('bengali-khichuri', 6, 'Rest off the heat for 5 minutes, fluff with a fork, and serve with fresh herbs.'),
  ('dal-tadka-rice', 1, 'Rinse the pigeon pea split (toor dal), raw and cook it with water until soft; mash lightly for a creamy texture.'),
  ('dal-tadka-rice', 2, 'Heat ghee or oil in a small pan and add cumin, turmeric, ginger and garlic.'),
  ('dal-tadka-rice', 3, 'Add tomato and onion and cook until the mixture is soft and aromatic.'),
  ('dal-tadka-rice', 4, 'Stir the tempering into the cooked lentils and add water to reach the consistency you like.'),
  ('dal-tadka-rice', 5, 'Simmer gently for 8 minutes, stirring occasionally so the lentils do not catch.'),
  ('dal-tadka-rice', 6, 'Taste, adjust salt and spice, garnish with coriander, and serve with rice or flatbread.'),
  ('paneer-biryani', 1, 'Rinse the rice until the water runs mostly clear, then soak for 10 minutes and drain.'),
  ('paneer-biryani', 2, 'Chop the aromatics and prepare the vegetables or protein before heating the pan.'),
  ('paneer-biryani', 3, 'Warm oil, bloom cumin and whole spices, then cook the onion until soft.'),
  ('paneer-biryani', 4, 'Add the paneer, tomato and seasoning; stir until coated with the spice base.'),
  ('paneer-biryani', 5, 'Add rice and measured water, bring to a simmer, cover, and cook until the grains are tender.'),
  ('paneer-biryani', 6, 'Rest off the heat for 5 minutes, fluff with a fork, and serve with fresh herbs.'),
  ('chicken-biryani', 1, 'Rinse the rice until the water runs mostly clear, then soak for 10 minutes and drain.'),
  ('chicken-biryani', 2, 'Chop the aromatics and prepare the vegetables or protein before heating the pan.'),
  ('chicken-biryani', 3, 'Warm oil, bloom cumin and whole spices, then cook the onion until soft.'),
  ('chicken-biryani', 4, 'Add the chicken breast, raw, tomato and seasoning; stir until coated with the spice base.'),
  ('chicken-biryani', 5, 'Add rice and measured water, bring to a simmer, cover, and cook until the grains are tender.'),
  ('chicken-biryani', 6, 'Rest off the heat for 5 minutes, fluff with a fork, and serve with fresh herbs.'),
  ('palak-paneer', 1, 'Wash and cut the main ingredient into even pieces; prepare the onion, tomato, ginger and garlic.'),
  ('palak-paneer', 2, 'Heat oil in a pan and cook the aromatics slowly until soft and fragrant.'),
  ('palak-paneer', 3, 'Add turmeric and chilli to the pan and stir for 30 seconds so the spices do not burn.'),
  ('palak-paneer', 4, 'Add the paneer and turn it through the masala until coated.'),
  ('palak-paneer', 5, 'Add a little water or coconut milk, cover, and simmer until the centre is cooked and the sauce thickens.'),
  ('palak-paneer', 6, 'Taste for salt and spice, finish with coriander, and serve with rice or flatbread.'),
  ('kerala-fish-curry', 1, 'Wash and cut the main ingredient into even pieces; prepare the onion, tomato, ginger and garlic.'),
  ('kerala-fish-curry', 2, 'Heat oil in a pan and cook the aromatics slowly until soft and fragrant.'),
  ('kerala-fish-curry', 3, 'Add turmeric and chilli to the pan and stir for 30 seconds so the spices do not burn.'),
  ('kerala-fish-curry', 4, 'Add the rohu fish, raw and turn it through the masala until coated.'),
  ('kerala-fish-curry', 5, 'Add a little water or coconut milk, cover, and simmer until the centre is cooked and the sauce thickens.'),
  ('kerala-fish-curry', 6, 'Taste for salt and spice, finish with coriander, and serve with rice or flatbread.'),
  ('vegetable-fried-rice', 1, 'Rinse the rice until the water runs mostly clear, then soak for 10 minutes and drain.'),
  ('vegetable-fried-rice', 2, 'Chop the aromatics and prepare the vegetables or protein before heating the pan.'),
  ('vegetable-fried-rice', 3, 'Warm oil, bloom cumin and whole spices, then cook the onion until soft.'),
  ('vegetable-fried-rice', 4, 'Add the mixed seasonal vegetables, tomato and seasoning; stir until coated with the spice base.'),
  ('vegetable-fried-rice', 5, 'Add rice and measured water, bring to a simmer, cover, and cook until the grains are tender.'),
  ('vegetable-fried-rice', 6, 'Rest off the heat for 5 minutes, fluff with a fork, and serve with fresh herbs.'),
  ('one-pot-tomato-pasta', 1, 'Cook the noodles according to the packet directions, drain, and rinse briefly with cool water.'),
  ('one-pot-tomato-pasta', 2, 'Slice the vegetables and main ingredient; stir together the soy sauce and a little water.'),
  ('one-pot-tomato-pasta', 3, 'Heat oil in a wok and briefly cook the garlic and main ingredient.'),
  ('one-pot-tomato-pasta', 4, 'Add the vegetables and stir-fry over high heat until just tender.'),
  ('one-pot-tomato-pasta', 5, 'Add the noodles and sauce; toss until evenly coated and hot.'),
  ('one-pot-tomato-pasta', 6, 'Taste, adjust seasoning, and serve straight from the pan.'),
