-- Seed data for KhaanaKya?
-- Sample catalog with 20 varied recipes, ingredients, and computed nutrition

-- Regions
on conflict (id) do update set name = excluded.name;

-- Cuisines
on conflict (id) do update set name = excluded.name, region_id = excluded.region_id;

-- Ingredients (complete food catalog)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  price_per_kg_inr = excluded.price_per_kg_inr,
  grams_per_piece = excluded.grams_per_piece,
  grams_per_ml = excluded.grams_per_ml,
  gluten = excluded.gluten,
  dairy = excluded.dairy,
  nuts = excluded.nuts,
  peanuts = excluded.peanuts,
  soy = excluded.soy,
  egg = excluded.egg,
  fish = excluded.fish,
  shellfish = excluded.shellfish,
  sesame = excluded.sesame,
  is_onion_garlic = excluded.is_onion_garlic;

-- Reference nutrition per 100g for ingredients
on conflict (ingredient_id) do update set
  kcal_per_100g = excluded.kcal_per_100g,
  protein_g_per_100g = excluded.protein_g_per_100g,
  carbs_g_per_100g = excluded.carbs_g_per_100g,
  fat_g_per_100g = excluded.fat_g_per_100g,
  fiber_g_per_100g = excluded.fiber_g_per_100g,
  sugar_g_per_100g = excluded.sugar_g_per_100g,
  sodium_mg_per_100g = excluded.sodium_mg_per_100g;

-- Sample Recipes (20 recipes across meals, regions, and diets)
on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  meal_type = excluded.meal_type,
  cuisine_id = excluded.cuisine_id,
  prep_minutes = excluded.prep_minutes,
  cook_minutes = excluded.cook_minutes,
  difficulty = excluded.difficulty,
  servings = excluded.servings,
  diet_type = excluded.diet_type,
  spice_level = excluded.spice_level,
  cost_per_serving_inr = excluded.cost_per_serving_inr,
  image_url = excluded.image_url;

-- Recipe Ingredients
on conflict (recipe_id, ingredient_id) do update set
  quantity = excluded.quantity,
  unit = excluded.unit,
  is_optional = excluded.is_optional;

-- Recipe Steps
on conflict (recipe_id, step_number) do update set
  instruction = excluded.instruction;

-- Tags and Recipe Tags
on conflict (id) do update set name = excluded.name;

on conflict (recipe_id, tag_id) do nothing;
